    pointer-events: auto !important;
    visibility: visible !important;
    display: block !important;
  }
}

/* ════════ LIGHT MODE ════════ */
[data-theme="light"] {
  color-scheme: light;

  /* core palette */
  --tp-bg-base: #faf8ff;
  --tp-bg-surface: #ffffff;
  --tp-bg-elevated: #f5f0ff;
  --tp-bg-inset: #efe8ff;
  --tp-chat-bg: #e7deff;
  --tp-chat-tint: rgba(208, 198, 242, 0.93);
  --tp-user-tint: rgba(255, 238, 248, 0.94);
  --tp-bot-tint: rgba(238, 248, 255, 0.94);

  --tp-text-primary: #26164a;
  --tp-text-secondary: #8050b8;
  --tp-text-muted: #a080c8;
  --tp-text-italics: #8758ac;
  --tp-text-quote: #588abe;
  --tp-text-underline: #da6c9e;
  --tp-text-inverted: #ffffff;

  --tp-pink: #f8acd2;
  --tp-pink-soft: #ffd6ee;
  --tp-purple: #bcacff;
  --tp-purple-soft: #e8daff;
  --tp-blue: #a8d2ff;
  --tp-blue-soft: #eef6ff;
  --tp-mint: #9edede;
  --tp-border: rgba(190, 168, 228, 0.8);
  --tp-shadow: rgba(155, 130, 210, 0.5);

  --tp-rainbow: linear-gradient(90deg, #ff9de2, #c084fc, #818cf8, #7dd3fc, #6ee7b7, #fde68a, #fca5a5, #ff9de2);
  --tp-rainbow-vertical: linear-gradient(180deg, #ff9de2, #c084fc, #818cf8, #7dd3fc, #6ee7b7, #fde68a, #fca5a5, #ff9de2);

  --background: var(--tp-bg-base);
  --marinara-app-background-paint: var(--tp-bg-base);
  --foreground: var(--tp-text-primary);

  --card: rgba(255, 255, 255, 0.97);
  --card-foreground: var(--tp-text-primary);
  --popover: var(--tp-bg-surface);
  --popover-foreground: var(--tp-text-primary);

  --primary: var(--tp-text-secondary);
  --primary-foreground: var(--tp-text-inverted);

  --secondary: var(--tp-bg-elevated);
  --secondary-foreground: var(--tp-text-primary);

  --muted: var(--tp-bg-inset);
  --muted-foreground: var(--tp-text-muted);

  --accent: var(--tp-purple-soft);
  --accent-foreground: var(--tp-text-primary);

  --destructive: #e54666;
  --destructive-foreground: var(--tp-text-inverted);

  --border: var(--tp-border);
  --input: var(--tp-border);
  --ring: var(--tp-purple);
  --radius: 1rem;

  --sidebar: var(--tp-bg-elevated);
  --sidebar-foreground: var(--tp-text-primary);
  --sidebar-border: var(--tp-border);
  --sidebar-accent: var(--tp-purple-soft);
  --sidebar-accent-foreground: var(--tp-text-primary);

  --glow-primary: rgba(190, 168, 228, 0.3);
  --glow-accent: rgba(248, 172, 210, 0.3);

  --marinara-app-accent-solid: var(--tp-purple);
  --marinara-app-accent-gradient: linear-gradient(90deg, var(--tp-pink), var(--tp-purple), var(--tp-mint));
  --marinara-chat-chrome-accent: var(--tp-purple);
  --marinara-chat-chrome-accent-gradient: var(--marinara-app-accent-gradient);
  --marinara-chat-chrome-text: var(--tp-text-primary);
  --marinara-chat-chrome-panel-muted: #6b5b8a;

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-xl: 24px;

  /* rest of the sillier rules */
  body,
  .app-shell,
  #root,
  #main,
  .main-container,
  .app-background,
  .chat-container,
  .chat-background,
  .message-list,
  .chat-messages,
  .chat-view,
  .conversation-pane,
  .mari-chat-shell,
  .mari-chat-background {
    background-color: var(--background) !important;
    color: var(--foreground) !important;
  }

  ::selection {
    background: rgba(221, 213, 245, 1) !important;
    color: #18171a !important;
  }

  .glass,
  .glass-strong,
  .card,
  .panel,
  .sidebar,
  .drawer,
  .modal-content,
  .settings-section,
  .chat-list,
  .character-card,
  .persona-card {
    background-color: var(--card) !important;
    border: 1px solid var(--tp-border) !important;
    border-radius: var(--radius-md) !important;
  }

  .card:hover,
  .character-card:hover,
  .persona-card:hover {
    border-color: var(--tp-purple) !important;
    box-shadow: 0 0 12px var(--glow-primary) !important;
  }

  .menu,
  .dropdown,
  .popover,
  .tooltip,
  .toast {
    background-color: var(--popover) !important;
    border: 1px solid var(--tp-border) !important;
    box-shadow: 0 0 14px var(--glow-primary) !important;
  }

  .tag,
  .badge {
    background-color: var(--tp-purple-soft) !important;
    color: var(--tp-text-secondary) !important;
    border: 1px solid var(--tp-border) !important;
    border-radius: 999px !important;
    padding: 2px 8px !important;
  }

  hr,
  .divider {
    border-color: var(--tp-border) !important;
  }

  code,
  pre,
  .code-block,
  .mari-message-content .mari-md-inline-code,
